public static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000000000L;
    long month = (timeBucket / 100000000) % 100;
    long day = (timeBucket / 1000000) % 100;
    long hour = (timeBucket / 10000) % 100;
    long minute = (timeBucket / 100) % 100;
    long second = timeBucket % 100;

    long newDay = day - (day % dayStep);
    return year * 10000000000L + month * 100000000 + newDay * 1000000 + hour * 10000 + minute * 100 + second;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index and length out of bounds");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            i++; // Skip the next character as it forms a surrogate pair
            size += 4;
        }
    }
    return size;
}

