public class StringUnescape {

    private static final Pattern ESCAPE_PATTERN = Pattern.compile("\\\\([\\\\\"'\\\\n\\\\r\\\\t\\\\b\\\\f])");
    private static final Pattern QUOTE_PATTERN = Pattern.compile("\"|'");
    private static final Pattern NEWLINE_PATTERN = Pattern.compile("\\\\n");
    private static final Pattern RETURN_PATTERN = Pattern.compile("\\\\r");
    private static final Pattern TAB_PATTERN = Pattern.compile("\\\\t");
    private static final Pattern BACKSPACE_PATTERN = Pattern.compile("\\\\b");
    private static final Pattern FORM_FEED_PATTERN = Pattern.compile("\\\\f");

    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        Matcher matcher = ESCAPE_PATTERN.matcher(str);
        StringBuffer sb = new StringBuffer();

        while (matcher.find()) {
            String escapeChar = matcher.group(1);
            switch (escapeChar) {
                case "\\":
                    matcher.appendReplacement(sb, "\\\\");
                    break;
                case "\"":
                    matcher.appendReplacement(sb, "\"");
                    break;
                case "'":
                    matcher.appendReplacement(sb, "'");
                    break;
                case "n":
                    matcher.appendReplacement(sb, "\n");
                    break;
                case "r":
                    matcher.appendReplacement(sb, "\r");
                    break;
                case "t":
                    matcher.appendReplacement(sb, "\t");
                    break;
                case "b":
                    matcher.appendReplacement(sb, "\b");
                    break;
                case "f":
                    matcher.appendReplacement(sb, "\f");
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: " + escapeChar);
            }
        }
        matcher.appendTail(sb);

        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(unescapeJava("\\\"Hello, \\'World\\'!\\n\\t\\r\\b\\f\""));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

