public final class UriMatcher {
    private final Pattern pattern;
    private final List<String> variableNames;
    private final Pattern matchPattern;

    public UriMatcher(String uriTemplate) {
        this.pattern = Pattern.compile(uriTemplate);
        this.variableNames = extractVariableNames(uriTemplate);
        this.matchPattern = Pattern.compile("\\\\{(" + String.join("|", variableNames) + ")\\\\}");
    }

    private List<String> extractVariableNames(String uriTemplate) {
        List<String> variableNames = new ArrayList<>();
        Matcher matcher = pattern.matcher(uriTemplate);
        while (matcher.find()) {
            variableNames.add(matcher.group(1));
        }
        return variableNames;
    }

    public MatchResult match(CharSequence uri) {
        if (uri == null) {
            return null;
        }
        Matcher matcher = pattern.matcher(uri);
        if (!matcher.matches()) {
            return null;
        }
        Map<String, String> match = new HashMap<>();
        for (String name : variableNames) {
            match.put(name, matcher.group(variableNames.indexOf(name) + 1));
        }
        return new MatchResult(uri, match);
    }

    public static class MatchResult {
        private final CharSequence uri;
        private final Map<String, String> match;

        public MatchResult(CharSequence uri, Map<String, String> match) {
            this.uri = uri;
            this.match = match;
        }

        public CharSequence getUri() {
            return uri;
        }

        public Map<String, String> getMatch() {
            return match;
        }

        @Override
        public String toString() {
            return "MatchResult{" +
                    "uri='" + uri + '\'' +
                    ", match=" + match +
                    '}';
        }
    }
}

