public String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            if (i < input.length()) {
                char escapedChar = input.charAt(i);
                switch (escapedChar) {
                    case 'n':
                        result.append('\n');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case 'b':
                        result.append('\b');
                        break;
                    case 'f':
                        result.append('\f');
                        break;
                    case '\\':
                        result.append('\\');
                        break;
                    case '"':
                        result.append('"');
                        break;
                    case '\'':
                        result.append('\'');
                        break;
                    default:
                        result.append(escapedChar);
                        break;
                }
            }
        } else {
            result.append(c);
        }
        i++;
    }
    return result.toString();
}

